import { decodeEventLog } from "viem";
import { describe, expect, it } from "vitest";
import { messageTransmitterV2Abi, tokenMessengerV2Abi } from "./index.js";

// Logs from real Base Sepolia transactions. The burn is
// 0xd449f392689b8ad1a5182f691289d366c152a0f03775434092fc15085786c92e and the
// receive 0x86b617da6c8417d794ed0397fa8f1561c55ccd5ad68660be444dcded7344fc10;
// Circle's Iris record of each agrees with the values below.
const depositForBurnLog = {
  topics: [
    "0x0c8c1cbdc5190613ebd485511d4e2812cfa45eecb79d845893331fedad5130a5",
    "0x000000000000000000000000036cbd53842c5426634e7929541ec2318f3dcf7e",
    "0x0000000000000000000000001ac614c66e2d3bcae310605dc6bd7f470cbdc150",
    "0x00000000000000000000000000000000000000000000000000000000000003e8",
  ] as [`0x${string}`, ...`0x${string}`[]],
  data: "" as `0x${string}`,
};

const messageReceivedLog = {
  topics: [
    "0xff48c13eda96b1cceacc6b9edeedc9e9db9d6226afbc30146b720c19d3addb1c",
    "0x0000000000000000000000009409b0a0eb0c19e1a26001109c005c5bd6e0e550",
    "0xfddd35b9023127aee2e813876c0501a30af753f1e387dc28fd5b5136c6a78be6",
    "0x00000000000000000000000000000000000000000000000000000000000003e8",
  ] as [`0x${string}`, ...`0x${string}`[]],
  data: "" as `0x${string}`,
};

describe("event ABIs decode real V2 logs", () => {
  it("DepositForBurn", () => {
    const { args } = decodeEventLog({
      abi: tokenMessengerV2Abi,
      eventName: "DepositForBurn",
      ...depositForBurnLog,
    });
    expect(args).toMatchObject({
      burnToken: "0x036CbD53842c5426634e7929541eC2318f3dCF7e",
      amount: 200000n,
      depositor: "0x1Ac614c66E2d3BCaE310605dC6bD7f470cBDc150",
      mintRecipient:
        "0x000000000000000000000000853b2a079d31f829c0d42c9f4afc39750eb37629",
      destinationDomain: 26,
      minFinalityThreshold: 1000,
    });
  });

  it("MessageReceived", () => {
    const { args } = decodeEventLog({
      abi: messageTransmitterV2Abi,
      eventName: "MessageReceived",
      ...messageReceivedLog,
    });
    expect(args).toMatchObject({
      sourceDomain: 2,
      nonce:
        "0xfddd35b9023127aee2e813876c0501a30af753f1e387dc28fd5b5136c6a78be6",
      finalityThresholdExecuted: 1000,
    });
  });
});
